"""Twelve advanced physics problems and eight logic/computational puzzles."""
def add_items(add):
    add('Q31','physics','שלושה מצבי תנודה','Three masses m,2m,m lie on a frictionless line between fixed walls. Four identical springs of stiffness k connect left wall--m--2m--m--right wall. For small longitudinal oscillations about equilibrium, what is omega_max^2/omega_min^2 for the three normal modes?','שלוש מסות m,2m,m בין שני קירות, מחוברות בארבעה קפיצים זהים k ללא חיכוך. מה יחס ריבוע התדירות הגבוהה ביותר לנמוכה ביותר בתנודות אורכיות קטנות?','(7+3*sqrt(5))/2',['3+2*sqrt(2)','(3+sqrt(5))/2','4'],'ל־λ=ω²m/k המצב האנטי־סימטרי נותן 2. הסימטריים נותנים λ²−3λ+1=0. יחס השורשים הוא (7+3√5)/2.')
    add('Q32','physics','אנרגיה במסגרת נעה','In one laboratory frame A moves at +3c/5 and particle B of rest mass m moves at -4c/5 along the same axis. What is the total relativistic energy of B measured in the inertial rest frame of A?','במעבדה A נע ב־‎+3c/5 ו־B שמסת המנוחה שלו m נע ב־‎−4c/5. מה האנרגיה הכוללת של B במסגרת המנוחה של A?','(37/12)*m*c^2',['(35/12)*m*c^2','(25/12)*m*c^2','(37/25)*m*c^2'],'γיחסי=γAγB(1−vAvB/c²)=(5/4)(5/3)(37/25)=37/12. האנרגיה γmc².',['https://openstax.org/books/university-physics-volume-3/pages/5-3-time-dilation'])
    add('Q33','physics','עבודה מרבית ממאגרים סופיים','Two bodies initially at 400 K and 100 K each have constant heat capacity 10 J/K. An ideal reversible heat engine operates between them until no more work can be extracted. They exchange no heat with the outside; the engine completes cycles and stores no net energy. What is the maximum work output?','גופים ב־400 וב־100 קלווין, כל אחד בקיבול חום קבוע 10 ג׳אול לקלווין. מנוע הפיך מוציא עבודה עד שיווי משקל, ללא חום החוצה וללא אגירת אנרגיה במנוע. מה העבודה המרבית?','1000 J',['750 J','1500 J','500 J'],'אנטרופיה נשמרת: Tf=√(400×100)=200 K. איבוד אנרגיה כולל 10(400+100−2×200)=1000 J.',['https://www.ocw.mit.edu/ans7870/16/16.unified/thermoF03/chapter_7.htm'])
    add('Q34','physics','קבלים עם קוטביות הפוכה ודיאלקטרי','Two capacitors C and 2C are separately charged to voltage magnitude V, then disconnected from all batteries. They are connected in parallel with opposite polarity and allowed to settle through arbitrarily small positive wire resistance. Still connected and isolated, a dielectric of relative permittivity 3 is slowly inserted to fill only the original C capacitor, without changing plate geometry. What fraction of the total initial stored electrical energy remains stored in both at the end?','קבלים C ו־2C נטענים בנפרד לגודל מתח V, מנותקים מהסוללות ומחוברים במקביל בקוטביות הפוכה עד התייצבות דרך התנגדות חיובית קטנה. עדיין מחוברים ומבודדים, מכניסים לקבל C דיאלקטרי יחסי 3 שממלאו בלי שינוי גאומטריה. איזה חלק מהאנרגיה ההתחלתית הכוללת נשאר בסוף?','1/15',['1/9','3/5','5/9'],'מטען הצומת CV−2CV=−CV. קיבול סופי 3C+2C=5C; Uf=CV²/10. במקור Ui=3CV²/2. היחס 1/15.',['https://openstax.org/books/university-physics-volume-2/pages/8-4-capacitor-with-a-dielectric'])
    add('Q35','physics','שינוי פתאומי באוסצילטור קוונטי','A one-dimensional quantum harmonic oscillator of mass m and angular frequency omega starts in its ground state. Its frequency is suddenly doubled to 2*omega without changing m. Immediately afterwards its energy is measured. What is the probability of obtaining the NEW ground-state energy hbar*omega?','אוסצילטור קוונטי במצב היסוד בתדירות זוויתית omega. מכפילים אותה פתאום בלי לשנות מסה. מה ההסתברות למדוד מיד את אנרגיית היסוד החדשה hbar*omega?','2*sqrt(2)/3',['4/5','1/sqrt(2)','2/3'],'המצב לא משתנה ברגע הקפיצה. חפיפת גאוסיאני היסוד בריבוע 2√(ωω\u0027)/(ω+ω\u0027). עם ω\u0027=2ω מתקבל 2√2/3.',['https://openstax.org/books/university-physics-volume-3/pages/7-5-the-quantum-harmonic-oscillator'])
    add('Q36','physics','סיבובי ספין עוקבים','A spin-1/2 particle starts in |+z>. First it evolves under Hx=(hbar*Omega/2)*sigma_x for time pi/(3*Omega), then under Hy=(hbar*Omega/2)*sigma_y for time pi/(4*Omega), without intermediate measurement. What is the probability that a final z-spin measurement gives +hbar/2?','ספין חצי מתחיל ב־|+z>. פועל Hx=(hbar*Omega/2)*sigma_x במשך pi/(3*Omega), ואז Hy=(hbar*Omega/2)*sigma_y במשך pi/(4*Omega), ללא מדידה באמצע. מה הסיכוי למדוד ב־z את ‎+hbar/2?','(4+sqrt(2))/8',['(4-sqrt(2))/8','3/4','1/2'],'סיבובי בלוך בזוויות π/3 סביב x ו־π/4 סביב y נותנים z=cos(π/3)cos(π/4)=√2/4. ההסתברות (1+z)/2=(4+√2)/8.')
    add('Q37','physics','יציבות בפוטנציאל מרכזי','Mass m moves in a central potential U(r)=a*r^4 with a>0. Around a circular orbit, make a small radial perturbation at fixed angular momentum. What is the ratio of the radial small-oscillation angular frequency to the original orbital angular frequency?','מסה m בפוטנציאל U(r)=a*r^4 עם a>0. מפריעים מעט רדיאלית למסלול מעגלי בתנע זוויתי קבוע. מה יחס תדירות התנודה הרדיאלית למסלולית?','sqrt(6)',['2','sqrt(3)','sqrt(5)'],'במסלול ω²=4ar²/m. הנגזרת השנייה של הפוטנציאל האפקטיבי 24ar², ולכן Ωr²=6ω².')
    add('Q38','physics','שינוי מסלול כבידתי','A negligible-mass satellite follows a Newtonian circular orbit of radius r around mass M. An instantaneous purely tangential impulse reduces its speed to half the circular speed without changing position. Ignore all later perturbations and collisions. What is the periapsis radius of the new Kepler orbit?','לוויין במסלול מעגלי ניוטוני ברדיוס r מקבל מתקף משיקי שמקטין מהירות לחצי בלי שינוי מיקום. מתעלמים מהפרעות ומהתנגשויות. מה רדיוס הפריאפסיס החדש?','r/7',['r/4','r/3','4*r/7'],'vis-viva נותנת 1/a=2/r−v²/(GM)=7/(4r), ולכן a=4r/7. הנקודה הנוכחית היא אפואפסיס r; פריאפסיס 2a−r=r/7.')
    add('Q39','physics','התאבכות חמש קרניים','Five coherent monochromatic waves have the same polarization and equal individual intensity I. At a point their phases are 0,pi/5,2*pi/5,3*pi/5,4*pi/5. What is the observed intensity divided by the intensity when all five phases are equal?','חמישה גלים קוהרנטיים באותו קיטוב, בעוצמה I לכל אחד, מגיעים בפאזות 0,pi/5,2pi/5,3pi/5,4pi/5. מה יחס העוצמה לעוצמה כשכל הפאזות שוות?','(6+2*sqrt(5))/25',['1/5','1/25','(6-2*sqrt(5))/25'],'אמפליטודה כוללת בגודל sin(5δ/2)/sin(δ/2)=1/sin(π/10)=1+√5. ריבועה 6+2√5, מול 25 בפאזות שוות.')
    add('Q40','physics','מעגל RLC בשתי תדירויות','A series circuit has ideal L and C and resistor R. At angular frequency omega, R=omega*L/2 and omega^2*L*C=2. The sinusoidal source has fixed RMS voltage. If frequency doubles while all components and RMS voltage stay unchanged, what is P_new/P_old for average power in R?','במעגל RLC טורי בתדירות omega מתקיים R=omega*L/2 ו־omega²LC=2. מכפילים תדירות בלי לשנות רכיבים ומתח RMS. מה יחס ההספק החדש לישן בנגד?','8/53',['2/7','4/13','1/4'],'במקור X=ωL−1/(ωC)=R. בכפולה X\u0027=2ωL−ωL/4=7R/2. היחס 2/(1+49/4)=8/53.')
    add('Q41','physics','נפילה עם גרר ריבועי','Mass m is released from rest and falls vertically with constant g and upward drag k*v^2. Let terminal speed v_t=sqrt(m*g/k). How far has it fallen when speed first reaches v_t/2?','מסה משתחררת ממנוחה בכבידה קבועה g וגרר מעלה k*v². v_t=√(mg/k). כמה נפלה עד שמהירותה מגיעה לראשונה ל־v_t/2?','(v_t^2/(2*g))*ln(4/3)',['(v_t^2/(2*g))*ln(3)','v_t^2/(8*g)','(v_t^2/g)*ln(2)'],'v dv/dx=g(1−v²/vt²), ולכן v²/vt²=1−exp(−2gx/vt²). מציבים 1/4: x=(vt²/2g)ln(4/3).')
    add('Q42','physics','חרוז על חישוק מסתובב','A bead slides frictionlessly on a circular hoop of radius R in a vertical plane. The hoop is driven at constant angular speed omega about its vertical diameter. Gravity is g and omega^2*R=2*g. Around either stable equilibrium away from the bottom, what is the small-oscillation angular frequency relative to the hoop?','חרוז מחליק ללא חיכוך בחישוק אנכי R, המסתובב במהירות קבועה omega סביב הקוטר האנכי. omega²R=2g. מה תדירות התנודות הקטנות יחסית לחישוק סביב שיווי משקל יציב שאינו התחתית?','sqrt(3*g/(2*R))',['sqrt(g/(2*R))','sqrt(2*g/R)','sqrt(3*g/R)'],'Veff=mgR(1−cosθ)−mω²R²sin²θ/2. בשיווי משקל cosθ=1/2, והתדירות בריבוע ω²sin²θ=3g/(2R).')
    add('Q43','logic','שישה דוברי אמת ושקר',"Each of A,B,C,D,E,F is a knight who always tells the truth or a knave who always lies. A says: B and C are of different kinds. B says: Exactly two of A,D,E are knights. C says: D is a knight if and only if F is a knave. D says: Exactly one of A,E is a knight. E says: B and F are both knaves. F says: At least three of A,B,C,D,E are knights. Which assignment is consistent?",'כל אחד מ־A עד F דובר אמת תמיד או שקרן תמיד. A: B ו־C שונים בסוגם. B: בדיוק שניים מ־A,D,E דוברי אמת. C: D דובר אמת אם ורק אם F שקרן. D: בדיוק אחד מ־A,E דובר אמת. E: B ו־F שקרנים. F: לפחות שלושה מ־A,B,C,D,E דוברי אמת. איזו השמה עקבית?','Knights A,B,D,F; knaves C,E',['Knights A,C,E; knaves B,D,F','Knights B,C,D; knaves A,E,F','Knights A,D,E,F; knaves B,C'],'סריקת 64 השמות המחייבת סוג דובר שווה לאמיתות טענתו נותנת פתרון יחיד: A,B,D,F אמת; C,E שקר.')
    add('Q44','logic','גשר לשישה אנשים','Six people cross a bridge with one torch at night. Times are 1,3,8,12,17,24 minutes. At most two cross together; every crossing requires the torch. A pair takes the slower time. Someone carries the torch back when needed, at the same individual times. What is the minimum total time to get everyone across?','שישה אנשים עוברים גשר בלפיד יחיד, בזמנים 1,3,8,12,17,24 דקות. עד שניים יחד, לכל מעבר הלפיד, זמן זוג הוא האיטי. גם בהחזרה אותם זמנים. מה המינימום הכולל?','53 minutes',['51 minutes','55 minutes','59 minutes'],'שולחים 17,24 בעזרת שני המהירים בעלות 31; את 8,12 בעלות 19; לבסוף 1,3 ב־3. סך 53. מינימליות מאומתת בחיפוש מסלול קצר בכל המצבים.')
    add('Q45','logic','מטבע חריג לא ידוע','Among 40 coins exactly one has a different weight, either heavier or lighter; all other coins have equal weight. No known genuine reference coin is supplied. With an ideal two-pan balance and adaptive weighings, can a strategy ALWAYS identify both the coin and whether it is heavier or lighter in at most four weighings?','בין 40 מטבעות אחד חריג, כבד או קל, וכל היתר שווים. אין מטבע תקין ידוע נוסף. האם ארבע שקילות אדפטיביות במאזני כפות יכולות תמיד לזהות גם מטבע וגם כבד/קל?','No; four weighings cannot guarantee both identifications',['Yes; four adaptive weighings always suffice','Yes; three weighings suffice','No finite number of weighings can do it'],'בשקילה ראשונה m מול m: בענף לא מאוזן 2m אפשרויות מחייבות m≤13. בענף מאוזן 2(40−2m)≤27 מחייב m≥14. סתירה. כפות עם מספרי מטבעות שונים לא מבטיחות מידע כשהבדל המשקל יכול להיות קטן כרצוננו.')
    add('Q46','logic','אסירים ומצב התחלתי לא ידוע','100 prisoners use a room with an on/off lamp initially in an unknown state. A designated counter turns it off whenever finding it on and increments a count. Each of the other 99 turns it on if finding it off, but may do so at most twice in total. No one else turns it off. Each visit is by one prisoner. What is the smallest count threshold guaranteeing that all 100 have visited when the counter announces, for any visit order and initial lamp state?','100 אסירים, נורה שמצבה ההתחלתי לא ידוע. מונה מכבה דלוקה ומגדיל ספירה. כל אחד מ־99 האחרים מדליק כבויה לכל היותר פעמיים. אף אחר לא מכבה. ביקור הוא של אחד. מה הסף הקטן ביותר שמבטיח שכולם ביקרו בכל סדר ובכל מצב התחלתי?','198',['99','100','199'],'בלי אסיר אחד, 98 האחרים מדליקים לכל היותר 196 פעמים, ועוד אחת אם הנורה התחילה דלוקה: 197. סף 198 מבטיח שכולם ביקרו; 197 לא. המונה ביקר בהכרח.')
    add('Q47','logic','כובעים עם אפשרות להימנע','Seven players independently receive fair red/blue hats. Each sees the six other hats, not their own. They agree on a deterministic strategy beforehand, then simultaneously say red, blue, or pass with no later communication. The team wins iff at least one guesses a color and every color guess is correct. What is the maximum win probability?','שבעה שחקנים בכובעי אדום/כחול הוגנים ובלתי תלויים. כל אחד רואה את האחרים. אחרי תכנון מראש עונים בו־זמנית אדום/כחול/נמנעים. ניצחון אם לפחות אחד מנחש וכולם נכונים. מה ההסתברות המרבית?','7/8',['1/2','3/4','15/16'],'קוד האמינג באורך 7 נותן 16 מרכזים מפסידים ו־112 שכנים מנצחים מתוך 128. כל מצב ניצחון יוצר שכן מפסיד על ידי היפוך כובע מנחש נכון; מצב מפסיד מכסה לכל היותר 7 כאלה. לכן החסם וההשגה הם 7/8.')
    add('Q48','logic','בדיקת ביצים אדפטיבית','A building has 100 floors and threshold F in {0,...,100}. An egg dropped from floor <=F survives, and from floor >F breaks. You have three identical eggs; surviving eggs can be reused, broken ones cannot. Drops may be adaptive. What is the minimum worst-case number of drops to determine F exactly?','בניין 100 קומות וסף F בין 0 ל־100. מקומה ≤F ביצה שורדת ומקומה >F נשברת. שלוש ביצים, שורדות לשימוש חוזר. מה מינימום ההטלות במקרה הגרוע ביותר לזיהוי הסף?','9',['8','10','14'],'ב־t הטלות עם 3 ביצים ניתן לכסות t+binomial(t,2)+binomial(t,3) קומות. ב־8: 92; ב־9: 129. לכן 9.')
    add('Q49','logic','ספירת מחרוזות באוטומט','How many binary strings of length 20 contain no substring 000 and have a total number of 1 bits divisible by 3? Leading zeros are allowed; substrings do not wrap around.','כמה מחרוזות בינאריות באורך 20 לא מכילות 000 ומספר ספרות ה־1 מתחלק ב־3? אפס מוביל מותר; אין חיבור מעגלי.','74493',['74490','74496','81234'],'תכנות דינמי על אורך, אפסים רצופים בסוף (0,1,2), ושארית מספר האחדות מודולו 3. סכום מצבי שארית 0 אחרי 20 צעדים הוא 74493. מאומת גם בסריקת 2^20 מחרוזות.')
    add('Q50','logic','חיבור מוצפן','In the base-10 alphametic DONALD + GERALD = ROBERT, different letters are different digits, all ten letters use all digits 0 through 9, and D,G,R cannot be zero. What is the six-digit number ROBERT in the solution?','בחידה DONALD+GERALD=ROBERT בבסיס 10, אותיות שונות הן ספרות שונות, עשר האותיות משתמשות ב־0 עד 9 ו־D,G,R אינם 0. מה ROBERT בפתרון?','723970',['724970','713970','723960'],'פתרון יחיד: 526485+197485=723970. D5,O2,N6,A4,L8,G1,E9,R7,B3,T0. מאומת בחיפוש נשיאות עמודה.')
